        self.refresh_token = refresh_token
        self.expires_in = expires_in
        self.token_type = token_type


class UserProfile:
    def __init__(self, sub, email, name):
        self.sub = sub
        self.email = email
        self.name = name

def summarize_audit_events(events):
    summary = {
        'total_events': len(events),
        'success_count': sum(1 for event in events if event['status'] == 'success'),
        'failure_count': sum(1 for event in events if event['status'] == 'failure')
    }
    return summary

def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if isinstance(value, str):
            moderated_claims[key] = value.strip()
        else:
            moderated_claims[key] = value
    return moderated_claims

